// Sample-based sound (spec §19), assets generated by scripts/audio/generate.mjs (ElevenLabs + Lyria).
// Sound carries state: the sizzle of a burning cord speeds up and brightens as its bomb gets closer,
// so the remaining time can be heard without looking. Music: menu, match, and a tension variant when
// two players remain out of a bigger field (same tempo and length as the match loop: beat-aligned swap).
import { CORD_WARN, SUB } from '../sim/constants';
import { tileOf } from '../sim';
import type { FireFront, GameState, SimEvent } from '../sim/types';
import { frontEtaTicks, sizzleFrequency, sizzleRate } from './eta';
import { AudioLibrary } from './library';
import {
  alignedOffset,
  boomId,
  countdownCue,
  countdownMark,
  musicLevel,
  musicScene,
  nextVariant,
  panForTile,
  roundStamp,
  sameRound,
  type CountdownMark,
  type MusicScene,
  type RoundStamp,
} from './logic';

const SIZZLE_VOICES = 4;
const MAX_ONE_SHOTS = 24;
const MASTER = 0.9;
const MUSIC_BUS = 0.42;
const MUSIC_FADE = 1.2;
const MUTE_KEY = 'meche.muted';
const STEP_GAP = 0.09; // s between two steps of the same player
const PITCH_SPREAD = 0.04;

/** Played even when the voice budget is full. */
const ESSENTIAL = new Set(['boom-small', 'boom-big', 'death', 'round-win', 'round-draw', 'match-win', 'count-tick', 'count-go', 'strike']);

const SCENE_TRACK: Record<MusicScene, string> = { menu: 'music-menu', match: 'music-match', tension: 'music-tension' };

interface SizzleVoice {
  readonly src: AudioBufferSourceNode;
  readonly filter: BiquadFilterNode;
  readonly gain: GainNode;
  readonly pan: StereoPannerNode;
}

interface MusicVoice {
  readonly id: string;
  readonly src: AudioBufferSourceNode;
  readonly gain: GainNode;
  /** Context time at which the loop position was 0 (loopStart). */
  readonly origin: number;
  readonly loopStart: number;
  readonly loopLength: number;
}

interface PlayOptions {
  readonly pan?: number;
  readonly gain?: number;
  readonly delay?: number;
  readonly rate?: number;
}

function readMuted(): boolean {
  try {
    return localStorage.getItem(MUTE_KEY) === '1';
  } catch {
    return false;
  }
}

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private sfxBus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private duck: GainNode | null = null;
  private readonly library = new AudioLibrary();
  private ready = false;
  private muted = readMuted();
  private sizzles: SizzleVoice[] = [];
  private music: MusicVoice | null = null;
  private fading: MusicVoice[] = [];
  private scene: MusicScene | null = null;
  private wantedScene: MusicScene = 'menu';
  private wantedLevel = 1;
  private oneShots = 0;
  private readonly variants = new Map<string, number>();
  private countdown: CountdownMark | null = null;
  private stepRound: RoundStamp | null = null;
  private readonly stepTile = new Int32Array(4).fill(-1);
  private readonly stepAt = new Float64Array(4);
  /** Preallocated ranking buffers: the closest bombs get the voices, no per-frame allocation. */
  private readonly slotEta = new Float64Array(SIZZLE_VOICES);
  private readonly slotFront: (FireFront | null)[] = new Array<FireFront | null>(SIZZLE_VOICES).fill(null);
  private readonly stats = { played: new Map<string, number>(), dropped: 0, sizzling: 0 };

  constructor() {
    if (typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('debug') === '1') {
      (window as unknown as { __mecheAudio: unknown }).__mecheAudio = { stats: () => this.debugStats() };
    }
  }

  /** Must be called from a user gesture (browser autoplay policy). */
  unlock(): void {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return;
    }
    const ctx = new AudioContext();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : MASTER;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -10;
    comp.ratio.value = 4;
    this.master.connect(comp).connect(ctx.destination);
    this.sfxBus = ctx.createGain();
    this.sfxBus.connect(this.master);
    this.duck = ctx.createGain();
    this.duck.connect(this.master);
    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = MUSIC_BUS;
    this.musicBus.connect(this.duck);
    void this.library.decodeAll(ctx).then(() => {
      this.ready = true;
      this.startSizzles();
    });
  }

  /** Silence everything while the tab is hidden. */
  suspend(): void {
    if (this.ctx && this.ctx.state === 'running') void this.ctx.suspend();
  }

  resume(): void {
    if (this.ctx && this.ctx.state === 'suspended') void this.ctx.resume();
  }

  toggleMute(): boolean {
    this.muted = !this.muted;
    try {
      localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0');
    } catch {
      // private mode: the choice lasts for the session only
    }
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(this.muted ? 0 : MASTER, this.ctx.currentTime, 0.02);
    return this.muted;
  }

  /** Continuous sound, once per frame: music scene and level, countdown cues, steps, fuse sizzles. */
  update(state: GameState | null, active: boolean): void {
    this.wantedScene = musicScene(state);
    this.wantedLevel = musicLevel(state, active);
    const ctx = this.ctx;
    if (!ctx || !this.ready) return;
    const now = ctx.currentTime;
    this.applyMusic(now);
    if (state) {
      const mark = countdownMark(state);
      const cue = countdownCue(this.countdown, mark);
      this.countdown = mark;
      if (cue === 'tick') this.play('count-tick', { gain: 0.9 });
      else if (cue === 'go') this.play('count-go');
      if (active) this.steps(state, now);
    }
    this.updateSizzles(state, active, now);
  }

  events(state: GameState, events: readonly SimEvent[]): void {
    if (!this.ctx || !this.ready) return;
    let crates = 0;
    for (const e of events) {
      switch (e.t) {
        case 'bomb-placed':
          this.play('place', { pan: panForTile(e.tile) });
          break;
        case 'action-denied':
          this.play('denied');
          break;
        case 'cord-extended': {
          this.play('unroll', { pan: panForTile(e.tile), rate: 1 + Math.min(0.3, e.length * 0.03) });
          const p = state.players[e.player];
          if (p && e.length >= p.cordMax - CORD_WARN && e.length < p.cordMax) this.play('spool-warning', { pan: panForTile(e.tile) });
          break;
        }
        case 'cord-rewound':
          this.play('rewind', { gain: 0.9 });
          break;
        case 'cord-lit':
          // A blast lighting a cord is a spark; a hand (or timer) lighting it is a match being struck.
          if (e.ignition.kind === 'blast') this.play('knot', { pan: panForTile(e.ignition.tile), gain: 0.8 });
          else this.play('strike', { pan: panForTile(e.ignition.tile) });
          break;
        case 'fire-jump':
          this.play('knot', { pan: panForTile(e.tile) });
          break;
        case 'hand-burnt':
          this.play('hand-burnt');
          break;
        case 'bomb-fuse': {
          const b = state.bombs.find((x) => x.id === e.bombId);
          this.play('wobble', { pan: b ? panForTile(b.tile) : 0 });
          break;
        }
        case 'explosion': {
          const ex = state.explosions.find((x) => x.id === e.explosionId);
          this.play(boomId(ex ? ex.tiles.length : 5), { pan: ex ? panForTile(ex.tile) * 0.6 : 0 });
          this.duckMusic();
          break;
        }
        case 'crate-destroyed':
          // A chain can break many crates in one tick: two clatters are enough to read it.
          if (crates < 2) this.play('crate', { pan: panForTile(e.tile), delay: crates * 0.05, gain: 0.85 });
          crates++;
          break;
        case 'player-died':
          this.play('death');
          break;
        case 'round-over':
          this.play(e.winner === null ? 'round-draw' : 'round-win');
          break;
      }
    }
  }

  /** Menu navigation sounds. Not wired by the app yet. */
  ui(kind: 'move' | 'select' | 'back'): void {
    if (this.ctx && this.ready) this.play(`ui-${kind}`);
  }

  /** Match won jingle. Not wired by the app yet (the sim does not know about matches). */
  matchWon(): void {
    if (this.ctx && this.ready) {
      this.play('match-win');
      this.duckMusic(2.5);
    }
  }

  private play(id: string, opts: PlayOptions = {}): void {
    const ctx = this.ctx!;
    const sound = this.library.get(id);
    if (!sound) return;
    if (this.oneShots >= MAX_ONE_SHOTS && !ESSENTIAL.has(id)) {
      this.stats.dropped++;
      return;
    }
    const buffer = sound.buffers[nextVariant(this.variants, id, sound.buffers.length)]!;
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.playbackRate.value = (opts.rate ?? 1) * (1 + (Math.random() * 2 - 1) * PITCH_SPREAD);
    const gain = ctx.createGain();
    gain.gain.value = opts.gain ?? 1;
    const pan = ctx.createStereoPanner();
    pan.pan.value = opts.pan ?? 0;
    src.connect(gain).connect(pan).connect(this.sfxBus!);
    this.oneShots++;
    src.onended = () => {
      this.oneShots--;
      pan.disconnect();
    };
    src.start(ctx.currentTime + (opts.delay ?? 0));
    this.stats.played.set(id, (this.stats.played.get(id) ?? 0) + 1);
  }

  /** One wooden tap each time a doll enters a new tile. */
  private steps(state: GameState, now: number): void {
    const stamp = roundStamp(state);
    if (!sameRound(this.stepRound, stamp)) this.stepTile.fill(-1);
    this.stepRound = stamp;
    for (const p of state.players) {
      if (!p || !p.alive) continue;
      const tile = tileOf(p.x, p.y);
      const last = this.stepTile[p.id]!;
      this.stepTile[p.id] = tile;
      if (last === -1 || tile === last || !p.moving) continue;
      if (now - this.stepAt[p.id]! < STEP_GAP) continue;
      this.stepAt[p.id] = now;
      this.play('step', { pan: panForTile(tile), gain: 0.8 });
    }
  }

  private startSizzles(): void {
    const ctx = this.ctx!;
    const sound = this.library.get('sizzle');
    if (!sound) return;
    const buffer = sound.buffers[0]!;
    const loopStart = (sound.entry.loopStartMs ?? 0) / 1000;
    const loopEnd = (sound.entry.loopEndMs ?? buffer.duration * 1000) / 1000;
    for (let i = 0; i < SIZZLE_VOICES; i++) {
      const src = ctx.createBufferSource();
      src.buffer = buffer;
      src.loop = true;
      src.loopStart = loopStart;
      src.loopEnd = loopEnd;
      const filter = ctx.createBiquadFilter();
      filter.type = 'peaking';
      filter.Q.value = 1.2;
      filter.gain.value = 6;
      filter.frequency.value = 900;
      const gain = ctx.createGain();
      gain.gain.value = 0;
      const pan = ctx.createStereoPanner();
      src.connect(filter).connect(gain).connect(pan).connect(this.sfxBus!);
      // Voices start at different points so overlapping cords don't phase into one sound.
      src.start(0, loopStart + ((loopEnd - loopStart) * i) / SIZZLE_VOICES);
      this.sizzles.push({ src, filter, gain, pan });
    }
  }

  private updateSizzles(state: GameState | null, active: boolean, now: number): void {
    // Keep the voices for the fronts closest to their bomb (fronts running to the hand rank last).
    const HAND = 1e9;
    let used = 0;
    if (active && state) {
      for (const f of state.fronts) {
        const key = frontEtaTicks(f) ?? HAND;
        if (used < SIZZLE_VOICES) {
          this.slotEta[used] = key;
          this.slotFront[used] = f;
          used++;
          continue;
        }
        let worst = 0;
        for (let i = 1; i < SIZZLE_VOICES; i++) if (this.slotEta[i]! > this.slotEta[worst]!) worst = i;
        if (key < this.slotEta[worst]!) {
          this.slotEta[worst] = key;
          this.slotFront[worst] = f;
        }
      }
    }
    this.stats.sizzling = used;
    for (let i = 0; i < this.sizzles.length; i++) {
      const v = this.sizzles[i]!;
      if (i >= used) {
        v.gain.gain.setTargetAtTime(0, now, 0.04);
        continue;
      }
      const eta = this.slotEta[i]!;
      const toHand = eta === HAND;
      v.src.playbackRate.setTargetAtTime(toHand ? 0.75 : sizzleRate(eta), now, 0.05);
      v.filter.frequency.setTargetAtTime(toHand ? 600 : sizzleFrequency(eta), now, 0.05);
      v.gain.gain.setTargetAtTime(toHand ? 0.28 : 0.75, now, 0.04);
      const tile = state ? this.frontTile(state, this.slotFront[i]!) : null;
      if (tile !== null) v.pan.pan.setTargetAtTime(panForTile(tile), now, 0.05);
    }
  }

  private frontTile(state: GameState, f: FireFront): number | null {
    for (const c of state.cords) {
      if (c.id !== f.cordId) continue;
      const node = c.nodes[f.progress < SUB / 2 ? f.from : f.to];
      return node ? node.tile : null;
    }
    return null;
  }

  private applyMusic(now: number): void {
    if (this.scene !== this.wantedScene) this.switchMusic(this.wantedScene, now);
    if (this.music) this.music.gain.gain.setTargetAtTime(this.wantedLevel, now, 0.25);
  }

  private switchMusic(scene: MusicScene, now: number): void {
    const ctx = this.ctx!;
    const id = SCENE_TRACK[scene];
    const sound = this.library.get(id);
    this.scene = scene;
    const old = this.music;
    this.music = null;
    if (old) {
      old.gain.gain.cancelScheduledValues(now);
      old.gain.gain.setValueAtTime(old.gain.gain.value, now);
      old.gain.gain.linearRampToValueAtTime(0, now + MUSIC_FADE);
      old.src.stop(now + MUSIC_FADE + 0.05);
      this.fading.push(old);
      old.src.onended = () => {
        old.gain.disconnect();
        this.fading = this.fading.filter((v) => v !== old);
      };
    }
    if (!sound) return;
    const buffer = sound.buffers[0]!;
    const loopStart = (sound.entry.loopStartMs ?? 0) / 1000;
    const loopEnd = (sound.entry.loopEndMs ?? buffer.duration * 1000) / 1000;
    const loopLength = loopEnd - loopStart;
    // Same loop length (match ↔ tension): continue at the same position in the bar.
    const offset = old && Math.abs(old.loopLength - loopLength) < 0.01 ? alignedOffset(now, old.origin, loopStart, loopLength) : loopStart;
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    src.loopStart = loopStart;
    src.loopEnd = loopEnd;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(this.wantedLevel, now + (old ? MUSIC_FADE : 0.4));
    src.connect(gain).connect(this.musicBus!);
    src.start(now, offset);
    this.music = { id, src, gain, origin: now - (offset - loopStart), loopStart, loopLength };
  }

  /** Music steps back briefly so the explosion reads. */
  private duckMusic(hold = 0.25): void {
    const ctx = this.ctx!;
    const g = this.duck!.gain;
    const now = ctx.currentTime;
    g.cancelScheduledValues(now);
    g.setValueAtTime(g.value, now);
    g.linearRampToValueAtTime(0.5, now + 0.03);
    g.setValueAtTime(0.5, now + 0.03 + hold);
    g.linearRampToValueAtTime(1, now + 0.03 + hold + 0.5);
  }

  private debugStats(): object {
    return {
      context: this.ctx?.state ?? 'none',
      ready: this.ready,
      decoded: this.library.decoded,
      total: this.library.total,
      failed: this.library.failed,
      muted: this.muted,
      scene: this.scene,
      music: this.music ? { id: this.music.id, level: +this.music.gain.gain.value.toFixed(2) } : null,
      sizzleVoices: this.sizzles.length,
      sizzling: this.stats.sizzling,
      oneShotsActive: this.oneShots,
      dropped: this.stats.dropped,
      played: Object.fromEntries(this.stats.played),
    };
  }
}
